INSERT OR REPLACE INTO apartman (id,sorrend,nev,emelet_hu,emelet_en,m2,fo,agy_hu,agy_en,kiemeles_hu,kiemeles_en,leiras_hu,leiras_en,festo_hu,festo_en,ar_hetkoznap,ar_hetvege,ar3_hetkoznap,ar3_hetvege,kepek) VALUES ('szonyi',1,'Szőnyi','emelet','upstairs',45,3,'franciaágy és ágyazható kanapé','double bed and sofa bed','A hálóból és a fürdőből is a Dunára lát.','River views from the bedroom and even the bathroom.','Az emeleti Szőnyi apartman nagy ablakai a Dunakanyarra néznek: a víz és a Visegrádi-hegység a nappaliból, a hálószobából és a fürdőszobából is látszik. 45 m², franciaágy és ágyazható kanapé, felszerelt konyha és terasz. Két felnőttnek tágas, egy harmadik vendég a kanapéágyon alszik.','The upstairs Szőnyi apartment looks out over the Danube Bend through large windows: the river and the Visegrád Hills are in view from the living room, the bedroom and even the bathroom. 45 m², a double bed and a sofa bed, a fully equipped kitchen and a terrace. Roomy for two, with a sofa bed for a third guest.','Szőnyi István a Dunakanyar festője: Zebegényben élt, és itt készültek legfontosabb képei. Egykori háza és műterme ma múzeum a faluban, kertjében ma is festészeti szabadiskola működik.','István Szőnyi is known as the painter of the Danube Bend. He lived in Zebegény and painted his most important works here. His former house and studio is now a museum in the village, and a free painting school still runs in its garden.',52000,58000,78000,87000,'["https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Szonyi-apartman-nappali-halo.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Szonyi-apartman-furdo-kilatas.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Szonyi-apartman-haloszoba.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Szonyi-apartman-konyha-nappali.jpg"]');
INSERT OR REPLACE INTO apartman (id,sorrend,nev,emelet_hu,emelet_en,m2,fo,agy_hu,agy_en,kiemeles_hu,kiemeles_en,leiras_hu,leiras_en,festo_hu,festo_en,ar_hetkoznap,ar_hetvege,ar3_hetkoznap,ar3_hetvege,kepek) VALUES ('bereny',2,'Berény','emelet','upstairs',45,3,'franciaágy és ágyazható kanapé','double bed and sofa bed','Terasz a víz fölött, Duna-kilátás a fürdőből is.','A terrace above the water, river views from the bathroom too.','Emeleti apartman nagy ablakokkal: a Dunakanyar a hálószobából és a fürdőszobából is látszik. 45 m², franciaágy és ágyazható kanapé, felszerelt konyha, terasz kilátással a vízre. Két felnőttnek tágas, egy harmadik vendég a kanapéágyon alszik.','An upstairs apartment with large windows: the Danube Bend is in view from the bedroom and even the bathroom. 45 m², a double bed and a sofa bed, a fully equipped kitchen and a terrace overlooking the river. Roomy for two, with a sofa bed for a third guest.','Berény Róbert Kossuth- és Munkácsy-díjas festőművész 1934-től ideje nagy részét Zebegényben töltötte, és itt festette több ismert képét.','Róbert Berény, winner of the Kossuth and Munkácsy Prizes, spent most of his time in Zebegény from 1934 and painted several of his best-known works here.',52000,58000,78000,87000,'["https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Bereny-apartman-nappali.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Bereny-terasz-kilatas.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Bereny-apartman-halo.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Bereny-apartman-furdo.jpg"]');
INSERT OR REPLACE INTO apartman (id,sorrend,nev,emelet_hu,emelet_en,m2,fo,agy_hu,agy_en,kiemeles_hu,kiemeles_en,leiras_hu,leiras_en,festo_hu,festo_en,ar_hetkoznap,ar_hetvege,ar3_hetkoznap,ar3_hetvege,kepek) VALUES ('amrita',3,'Amrita','földszint','ground floor',40,3,'franciaágy és ágyazható kanapé','double bed and sofa bed','Nagy terasz a Dunára és a Börzsönyre, üvegfalú fürdő.','A large terrace facing the Danube and the Börzsöny hills, a glass-walled bathroom.','Földszinti apartman külön hálótérrel és nagy terasszal, ahonnan a Duna és a Börzsöny vonulatai látszanak. A fürdőszoba üvegfalú, így a panoráma zuhanyzás közben is látszik. 40 m², franciaágy és ágyazható kanapé, felszerelt konyha. Két főre készült, pótággyal hárman is elférnek.','A ground-floor apartment with a separate sleeping area and a large terrace facing the Danube and the Börzsöny hills. The bathroom has glass walls, so the view stays with you in the shower. 40 m², a double bed and a sofa bed, a fully equipped kitchen. Designed for two, with room for a third guest on the sofa bed.','Amrita Sher-Gil India egyik legismertebb festője, félig magyar volt, és több nyarat töltött Zebegényben. Saját szavai szerint Delhi és London között Zebegény volt számára a világ közepe.','Amrita Sher-Gil, one of India''s best-known painters, was half Hungarian and spent several summers in Zebegény. In her own words, between Delhi and London, Zebegény was the centre of the world.',42000,48000,63000,72000,'["https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Amrita-apartman-nappali.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Amrita-apartman-halo.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Amrita-apartman-furdo.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Amrita-apartman-konyha.jpg"]');
INSERT OR REPLACE INTO apartman (id,sorrend,nev,emelet_hu,emelet_en,m2,fo,agy_hu,agy_en,kiemeles_hu,kiemeles_en,leiras_hu,leiras_en,festo_hu,festo_en,ar_hetkoznap,ar_hetvege,ar3_hetkoznap,ar3_hetvege,kepek) VALUES ('karpathy',4,'Kárpáthy','földszint','ground floor',40,3,'franciaágy és ágyazható kanapé','double bed and sofa bed','Nagy terasz a naplementékre, üvegfalú fürdő.','A large terrace for the sunsets, a glass-walled bathroom.','Földszinti apartman külön hálótérrel és nagy terasszal, ahonnan a Dunakanyar naplementéi látszanak. A fürdőszoba üvegfalú, így a panoráma zuhanyzás közben is látszik. 40 m², franciaágy és ágyazható kanapé, felszerelt konyha. Két főre készült, pótággyal hárman is elférnek.','A ground-floor apartment with a separate sleeping area and a large terrace for watching the sunset over the Danube Bend. The bathroom has glass walls, so the view stays with you in the shower. 40 m², a double bed and a sofa bed, a fully equipped kitchen. Designed for two, with room for a third guest on the sofa bed.','Kárpáthy Jenő festőművész Zebegényben élt és alkotott; olajképein többször megfestette a Dunát és a zebegényi tájat.','The painter Jenő Kárpáthy lived and worked in Zebegény, and painted the Danube and the Zebegény landscape many times in oil.',42000,48000,63000,72000,'["https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Karpathy-apartman-nappali.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Karpathy-terasz.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Karpathy-apartman-halo.jpg","https://akvarellzebegeny.hu/wp-content/uploads/2024/05/Karpathy-apartman-nappali-2.jpg"]');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('cim','Akvarell Apartmanház','Akvarell Apartment House');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('alcim','Négy apartman Zebegényben, panorámával a Dunára, a Pilisre és a Visegrádi-hegységre.','Four apartments in Zebegény, with views of the Danube, the Pilis and the Visegrád Hills.');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('bevezeto','Mind a négy apartman egy-egy festőről kapta a nevét, aki Zebegényben élt vagy alkotott. Közös kültéri jakuzzi, elektromosautó-töltő, ingyenes parkolás és wifi.','Each of the four apartments is named after a painter who lived or worked in Zebegény. Shared outdoor hot tub, EV charger, free parking and Wi-Fi.');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('gyerek','3–13 éves gyermek: 15 000 Ft/éj. 3 év alatt ingyenes. Egy éjszakás foglalás felára: 20 000 Ft. Idegenforgalmi adó: 750 Ft/fő/éj, 18 év felett.','Children aged 3–13: HUF 15,000 per night; under 3 free. One-night stay surcharge: HUF 20,000. Tourist tax: HUF 750 per person per night, over 18.');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('kihivas_cim','Zebegény 10-es kihívás','Zebegény 10 Challenge');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('kihivas_bev','Séta Zebegényben, tíz állomással, az Akvarelltől az Akvarellig.','A ten-stop walk around Zebegény, from Akvarell and back.');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('kihivas_bev2','Séta Zebegényben, tíz állomással. Az Akvarelltől indulsz, és oda érsz vissza. Közben a főtéri templom, a Kálvária-domb, a Héthíd és a Duna-part. Minden állomásnál koppints a „Megvan” gombra, és ha kedved van, küldj egy szelfit. Ahol jártál, ott kiszíneződik a térkép, a tizedik állomásra kész a festmény. Nincs időre, több részletben is bejárható.','A walk around Zebegény with ten stops. You start at Akvarell and finish there. On the way: the church on the main square, Calvary Hill, the Seven-Arch Bridge and the Danube bank. Tap “Found it” at each stop and send a selfie if you like. The map fills with colour wherever you have been, and by the tenth stop the painting is finished. There is no time limit, and you can do it in several parts.');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('ajandek','','');
INSERT OR REPLACE INTO tartalom (kulcs,hu,en) VALUES ('uzemelteto','Üzemeltető: Ferenczy Ernő Ervin egyéni vállalkozó · 2627 Zebegény, Csalogány utca 4.','Operator: Ernő Ervin Ferenczy, sole proprietor · 2627 Zebegény, Csalogány utca 4');
